import{c as a,Q as e,j as l,m as s}from"./chunks/framework.DOi4mjdC.js";const u=JSON.parse('{"title":"Alloc","description":"","frontmatter":{},"headers":[{"level":1,"title":"Alloc","slug":"alloc"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/基础API/资源管理/内存管理/LocalMemAllocator/Alloc.md","filePath":"api/SIMD-API/基础API/资源管理/内存管理/LocalMemAllocator/Alloc.md"}'),n={name:"api/SIMD-API/基础API/资源管理/内存管理/LocalMemAllocator/Alloc.md"};function o(i,t,p,r,d,c){return e(),l("div",null,[...t[0]||(t[0]=[s(`<h1 id="alloc" tabindex="-1">Alloc <a class="header-anchor" href="#alloc" aria-label="Permalink to &quot;Alloc&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>√</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>√</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>x</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>√</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>√</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>根据用户指定的逻辑位置、数据类型、数据长度返回对应的LocalTensor对象。</p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><ul><li><p>原型1：tileSize为模板参数</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 当tileSize为常量时，建议使用此接口，以获得更优的性能</span></span>
<span class="line"><span>template &lt;class DataType, uint32_t tileSize&gt; LocalTensor&lt;DataType&gt; __aicore__ inline Alloc()</span></span>
<span class="line"><span>template &lt;TPosition pos, class DataType, uint32_t tileSize&gt; __aicore__ inline LocalTensor&lt;DataType&gt; Alloc()</span></span></code></pre></div></li><li><p>原型2：tileSize为接口入参</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 当tileSize为动态参数时使用此接口</span></span>
<span class="line"><span>template &lt;class DataType&gt; LocalTensor&lt;DataType&gt; __aicore__ inline Alloc(uint32_t tileSize)</span></span>
<span class="line"><span>template &lt;TPosition pos, class DataType&gt; LocalTensor&lt;DataType&gt; __aicore__ inline Alloc(uint32_t tileSize)</span></span></code></pre></div></li><li><p>原型3：使用TensorTrait时使用此接口</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;class DataType&gt; LocalTensor&lt;DataType&gt; __aicore__ inline Alloc()</span></span></code></pre></div></li></ul><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 原型1和原型2模板参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>pos</td><td>TPosition位置，需要符合LocalMemAllocator中指定的Hardware物理位置（静态Tensor编程场景下，此参数可以省略）。</td></tr><tr><td>DataType</td><td>LocalTensor的数据类型，只支持基础数据类型，不支持TensorTrait类型。</td></tr><tr><td>tileSize</td><td>LocalTensor的元素个数，其数量不应超过当前物理位置剩余的内存空间。</td></tr></tbody></table><p><strong>表 2</strong> 原型2参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>tileSize</td><td>输入</td><td>LocalTensor的元素个数，其数量不应超过当前物理位置剩余的内存空间。 剩余的内存空间可以通过物理内存最大值与当前可用内存地址（GetCurAddr返回值）的差值来计算。</td></tr></tbody></table><p><strong>表 3</strong> 原型3模板参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>TensorTraitType</td><td>只支持传入TensorTrait类型，TensorTrait的数据类型/逻辑位置/Shape大小需要匹配LocalMemAllocator中指定的物理位置及其剩余空间。</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>根据用户输入构造的LocalTensor对象。</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><p>无</p><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;uint32_t v&gt;</span></span>
<span class="line"><span>using UIntImm = Std::integral_constant&lt;uint32_t, v&gt;;</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>AscendC::LocalMemAllocator allocator;</span></span>
<span class="line"><span>// 原型1：float类型，Tensor中有1024个元素，用户可以指定逻辑位置(或者不指定，由Alloc函数根据物理位置给出默认值，不影响功能)</span></span>
<span class="line"><span>auto tensor1 = allocator.Alloc&lt;AscendC::TPosition::VECIN, float, 1024&gt;();</span></span>
<span class="line"><span>auto tensor1 = allocator.Alloc&lt;float, 1024&gt;();</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 原型2：float类型，Tensor中有tileLength个元素，用户可以指定逻辑位置(或者不指定，由Alloc函数根据物理位置给出默认值，不影响功能)</span></span>
<span class="line"><span>auto tensor1 = allocator.Alloc&lt;AscendC::TPosition::VECIN, float&gt;(tileLength);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 原型3：用户指定逻辑位置VECIN，数据类型为float，Tensor中元素个数为16*16*16</span></span>
<span class="line"><span>auto shape = AscendC::MakeShape(UIntImm&lt;16&gt;{}, UIntImm&lt;16&gt;{}, UIntImm&lt;16&gt;{});</span></span>
<span class="line"><span>auto stride = AscendC::MakeStride(UIntImm&lt;0&gt;{}, UIntImm&lt;0&gt;{}, UIntImm&lt;0&gt;{});</span></span>
<span class="line"><span>auto layoutMake = AscendC::MakeLayout(shape, stride);</span></span>
<span class="line"><span>auto tensorTraitMake = AscendC::MakeTensorTrait&lt;float, AscendC::TPosition::VECIN&gt;(layoutMake);</span></span>
<span class="line"><span>auto tensor3 = allocator.Alloc&lt;decltype(tensorTraitMake)&gt;();</span></span></code></pre></div>`,20)])])}const g=a(n,[["render",o]]);export{u as __pageData,g as default};
